B.bk7=new A.A("Os dados s\xe3o utilizados exclusivamente para conectar contratantes a prestadores de servi\xe7os de constru\xe7\xe3o civil, permitir a comunica\xe7\xe3o entre as partes e enviar notifica\xe7\xf5es relevantes sobre or\xe7amentos e solicita\xe7\xf5es.",null,B.jv,null,null,null,null,null,null,null,null)
