B.bgq=new A.A("Utilizamos o Supabase para armazenamento seguro e autentica\xe7\xe3o, e o Firebase (Google) para envio de notifica\xe7\xf5es push. N\xe3o vendemos, alugamos ou compartilhamos dados pessoais com terceiros para fins de marketing.",null,B.jv,null,null,null,null,null,null,null,null)
B.bko=new A.A("4. Exclus\xe3o de Conta e Direitos do Usu\xe1rio (LGPD)",null,B.d_,null,null,null,null,null,null,null,null)
